type IconName = "chat"|"calendar"|"users"|"bell"|"settings"|"search"|"plus"|"send"|"info"|"map"|"mail"|"phone"|"sun"|"moon"|"chevron"|"more"|"document"|"book"|"shield"|"logout"|"close"|"check"|"trash"|"edit"|"menu";
type StructuredScheduleEntry = { section:string; day:string; startTime:string; endTime:string; courseCode:string; courseName:string; room:string };
type StructuredSchedule = { request:"full"|"specific"; section:string; entries:StructuredScheduleEntry[] };
// sources and createdAt are optional additions (approved): only new messages carry them; older saved messages load unchanged.
type Source = { id:string; title:string; category?:string };
type Message = { id:string; from:"user"|"ai"; text:string; proposal?:ScheduleProposal; schedule?:StructuredSchedule; dismissed?:boolean; sources?:Source[]; createdAt?:string };
// A failed request lives only in memory: it is shown with Retry and never saved as an AI reply.
type Failure = { text:string; error:string; proposal?:ScheduleProposal; added:boolean };
type Conversation = { id:string; title:string; createdAt:string; updatedAt:string; messages:Message[] };
type ScheduleProposal = { title:string; type:string; date:string; time?:string; reminder?:string; description?:string };
type Schoolwork = ScheduleProposal & { id:string; subject:string; dueDate:string; dueTime?:string; status:"pending"|"completed"; createdAt:string; updatedAt:string };
type Notice = { id:string; title:string; message:string; type:string; createdAt:string; read:boolean; relatedId?:string };
type Data = { conversations:Conversation[]; events:ScheduleProposal[]; schoolwork:Schoolwork[]; notifications:Notice[]; theme:"dark"|"light" };
const storeKey=(userId:string)=>`eagledesk.student.v2.${userId}`;
const initial:Data={conversations:[],events:[],schoolwork:[],notifications:[],theme:"dark"};
const uid=()=>crypto.randomUUID();
const load=(userId:string):Data=>{try{return {...initial,...JSON.parse(localStorage.getItem(storeKey(userId))||"{}")} as Data}catch{return initial}};
const fmt=(d:string)=>new Date(`${d}T12:00:00`).toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"});
const localDate=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
const daysLater=(date:string,n:number)=>{const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
function parseSchedule(text:string):ScheduleProposal|null{
  const s=text.trim(), lower=s.toLowerCase();
  const kind=lower.match(/\b(exam|midterm|final|quiz|assignment|homework|project|presentation|thesis|deadline|meeting|reminder)\b/);
  if(!kind)return null;
  let date:Date|undefined;
  const named=s.match(/\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2})(?:,?\s+(20\d{2}))?\b/i);
  const iso=s.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);
  const relative=s.match(/\b(today|tomorrow|day after tomorrow|next\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)|this\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)|\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday))\b/i);
  if(named){const year=Number(named[3]||new Date().getFullYear());date=new Date(year, new Date(`${named[1]} 1, ${year}`).getMonth(),Number(named[2]));if(!named[3]&&date<new Date(new Date().setHours(0,0,0,0)))date.setFullYear(year+1)}
  else if(iso)date=new Date(Number(iso[1]),Number(iso[2])-1,Number(iso[3]));
  else if(relative){date=new Date();date.setHours(0,0,0,0);const r=relative[0].toLowerCase();if(r==="tomorrow")date.setDate(date.getDate()+1);else if(r==="day after tomorrow")date.setDate(date.getDate()+2);else if(r!=="today"){const weekday=(relative[2]||relative[3]||relative[4]).toLowerCase();const target=["sunday","monday","tuesday","wednesday","thursday","friday","saturday"].indexOf(weekday);let diff=(target-date.getDay()+7)%7;if(r.startsWith("next "))diff=diff===0?7:diff+7;else if(diff===0)diff=7;date.setDate(date.getDate()+diff)}}
  if(!date||Number.isNaN(date.getTime()))return null;
  const dateStr=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;
  const time=s.match(/\b(1[0-2]|0?\d)(?::([0-5]\d))?\s*(am|pm)\b/i)?.[0];
  const type=/exam|midterm|final/.test(lower)?"Exam":kind[0][0].toUpperCase()+kind[0].slice(1).toLowerCase();
  let title="";
  const subject=s.match(/\b(?:for|about|in)\s+([\w][\w &'-]*(?:\s+[\w][\w&'-]*){0,3})/i)||s.match(/\b(?:have|has|a|an|my)\s+([\w][\w &'-]*(?:\s+[\w][\w&'-]*){0,3}?)\s+(?:exam|quiz|assignment|project|presentation|homework)\b/i);
  const dueSubject=s.match(/\bmy\s+([\w][\w &'-]*(?:assignment|project|exam|quiz|presentation|homework)[\w &'-]*)/i);
  if(subject)title=`${subject[1].replace(/[.!?]+$/,"" )} ${type}`;else if(dueSubject)title=dueSubject[1].replace(/[.!?]+$/,"" ).replace(/\b\w/g,c=>c.toUpperCase());else title=type;
  const before=s.match(/\b(\d+)\s+days?\s+before\b|\bone day before\b/i);
  const reminder=before?daysLater(dateStr,-(Number(before[1]||1))):undefined;
  return {title,type,date:dateStr,time,reminder,description:s};
}

const iconPaths:Record<IconName,ReactNode>={chat:<><path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4Z"/><path d="M8 9h8M8 13h5"/></>,calendar:<><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></>,users:<><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></>,bell:<><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M13.73 21a2 2 0 0 1-3.46 0"/></>,settings:<><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.55V21h-4v-.08A1.7 1.7 0 0 0 8.94 19.4a1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.6 15 1.7 1.7 0 0 0 3.08 14H3v-4h.08A1.7 1.7 0 0 0 4.6 8.94a1.7 1.7 0 0 0-.34-1.88L4.2 7l2.83-2.83.06.06A1.7 1.7 0 0 0 8.94 4.6 1.7 1.7 0 0 0 10 3.08V3h4v.08a1.7 1.7 0 0 0 1.06 1.52 1.7 1.7 0 0 0 1.88-.34L17 4.2 19.83 7l-.06.06a1.7 1.7 0 0 0-.34 1.88A1.7 1.7 0 0 0 20.92 10H21v4h-.08A1.7 1.7 0 0 0 19.4 15Z"/></>,search:<><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>,plus:<path d="M12 5v14M5 12h14"/>,send:<><path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/></>,info:<><circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/></>,map:<><path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></>,mail:<><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></>,phone:<path d="M22 16.9v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.34 1.78.65 2.63a2 2 0 0 1-.45 2.11L8.04 9.73a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.85.31 1.73.53 2.63.65A2 2 0 0 1 22 16.9Z"/>,sun:<><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.42-1.42M17.66 6.34l1.41-1.41"/></>,moon:<path d="M21 12.8A9 9 0 1 1 11.2 3 7 7 0 0 0 21 12.8Z"/>,chevron:<path d="m9 18 6-6-6-6"/>,more:<><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></>,document:<><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h6"/></>,book:<><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5Z"/><path d="M4 5.5v14A2.5 2.5 0 0 0 6.5 22H20"/></>,shield:<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/>,logout:<><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/></>,close:<path d="M18 6 6 18M6 6l12 12"/>,check:<path d="m20 6-11 11-5-5"/>,trash:<><path d="M3 6h18M8 6V4h8v2m3 0-1 14H6L5 6"/><path d="M10 11v5m4-5v5"/></>,edit:<><path d="m15 5 4 4M4 20l4-.8L19 8a2.8 2.8 0 0 0-4-4L4 15z"/></>,menu:<path d="M4 7h16M4 12h16M4 17h10"/>};
function Icon({name,size=20}:{name:IconName;size?:number}){return <svg className="icon" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{iconPaths[name]}</svg>}
function Button({children,variant="primary",icon,className="",...props}:{children?:ReactNode;variant?:"primary"|"secondary"|"ghost"|"danger"|"icon";icon?:IconName}&React.ButtonHTMLAttributes<HTMLButtonElement>){return <button className={`button button-${variant} ${className}`} {...props}>{icon&&<Icon name={icon}/>} {children}</button>}
function Avatar({initials}:{initials?:string}){const me=useContext(UserContext);return <span className="avatar">{initials??me.initials}</span>}
function Page({title,subtitle,children,actions}:{title:string;subtitle:string;children:ReactNode;actions?:ReactNode}){return <main className="page"><header className="page-header"><div><h1>{title}</h1><p>{subtitle}</p></div><div className="page-actions">{actions}</div></header>{children}</main>}

function Sidebar({page,setPage,openProfile,unread,menuOpen,history}:{page:string;setPage:(p:string)=>void;openProfile:()=>void;unread:number;menuOpen:boolean;history:{items:Conversation[];selected:string;onSelect:(id:string)=>void;onNew:()=>void;onDelete:(id:string)=>void}}){const me=useContext(UserContext);const items:[string,string,IconName][]=[["chats","Chat","chat"],["calendar","Personal Calendar","calendar"],["schoolwork","Schoolwork","document"],["notifications","Notifications","bell"],["contact","Contact Staff","users"],["settings","Settings","settings"]];return <aside className="sidebar"><div className="sidebar-logo"><Eagle size="sm"/><span className="sidebar-wordmark">EagleDesk</span></div><Button className="sidebar-new" icon="plus" onClick={history.onNew} aria-label="New chat"><span className="sidebar-new-label" aria-hidden="true">New chat</span></Button><nav className="nav-stack" aria-label="Main">{items.map(([id,label,icon])=>{const alert=id==="notifications"&&unread>0;return <Button key={id} variant="ghost" className={`nav-button ${page===id?"active":""}`} onClick={()=>setPage(id)} aria-label={alert?`${label}, ${unread} unread`:label} aria-current={page===id?"page":undefined}><Icon name={icon}/><span aria-hidden="true">{label}</span>{alert&&<i className="nav-dot"/>}</Button>})}</nav><section className="sidebar-recent" aria-label="Recent chats"><div className="history-label">Recent chats</div><HistoryList items={history.items} selected={history.selected} onSelect={history.onSelect} onDelete={history.onDelete} limit={8}/></section><button className="profile-button" onClick={openProfile} aria-label="Open profile menu" aria-expanded={menuOpen} aria-controls="profile-menu"><Avatar/><span className="profile-text" aria-hidden="true"><span className="profile-name">{me.name}</span><span className="profile-email">{me.email}</span></span><span className="profile-chevron" aria-hidden="true"><Icon name="more" size={16}/></span></button></aside>}
function MobileNav({page,setPage,unread}:{page:string;setPage:(p:string)=>void;unread:number}){const items:[string,string,IconName][]=[["chats","Chat","chat"],["calendar","Calendar","calendar"],["schoolwork","Work","document"],["notifications","Alerts","bell"],["contact","Contact","users"],["settings","Settings","settings"]];return <nav className="mobile-nav" aria-label="Main">{items.map(([id,label,icon])=><button key={id} className={page===id?"active":""} onClick={()=>setPage(id)} aria-current={page===id?"page":undefined}><Icon name={icon} size={20}/><span>{label}{id==="notifications"&&unread>0?` (${unread})`:""}</span></button>)}</nav>}

// Chat history list shared by the wide-screen sidebar ("Recent chats") and the drawer below 1280px.
// Search, grouping, selection, and deletion behave the same in both places.
function HistoryList({items,selected,onSelect,onDelete,limit}:{items:Conversation[];selected:string;onSelect:(x:string)=>void;onDelete:(id:string)=>void;limit?:number}){const [q,setQ]=useState("");const [expanded,setExpanded]=useState(false);const [pending,setPending]=useState<Conversation|null>(null);
  const filtered=useMemo(()=>items.filter(c=>(c.title+" "+(c.messages.at(-1)?.text||"")).toLowerCase().includes(q.toLowerCase())),[items,q]);
  const collapsible=!!limit&&!q&&filtered.length>limit;const shown=collapsible&&!expanded?filtered.slice(0,limit):filtered;
  const today=new Date().toDateString();const groups=[["Today",shown.filter(c=>new Date(c.updatedAt).toDateString()===today)],["Previous",shown.filter(c=>new Date(c.updatedAt).toDateString()!==today)]] as const;
  const when=(c:Conversation)=>new Date(c.updatedAt).toDateString()===today?new Date(c.updatedAt).toLocaleTimeString([], {hour:"numeric",minute:"2-digit"}):new Date(c.updatedAt).toLocaleDateString("en-US",{month:"short",day:"numeric"});
  return <div className="history"><label className="search"><Icon name="search" size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search conversations" aria-label="Search conversations"/></label><div className="conversation-list">{items.length===0&&<p className="empty-hint">Your conversations will appear here.</p>}{items.length>0&&filtered.length===0&&<p className="empty-hint" role="status">No conversations match “{q.trim()}”.</p>}{groups.map(([label,list])=>list.length>0&&<section key={label}><div className="history-label">{label}</div>{list.map(c=><div key={c.id} className={`conversation-row ${selected===c.id?"selected":""}`}><button onClick={()=>onSelect(c.id)} aria-current={selected===c.id?"true":undefined}><div className="conversation-copy"><div className="conversation-meta"><strong>{c.title}</strong><time dateTime={c.updatedAt}>{when(c)}</time></div><span>{c.messages.at(-1)?.text||"New conversation"}</span></div></button><button className="history-delete" onClick={()=>setPending(c)} aria-label={`Delete conversation: ${c.title}`}><Icon name="trash" size={16}/></button></div>)}</section>)}{collapsible&&<button className="history-more" onClick={()=>setExpanded(v=>!v)} aria-expanded={expanded}>{expanded?"Show less":`Show ${filtered.length-(limit??0)} more`}</button>}</div>{pending&&<ConfirmDialog title="Delete this chat?" message={`“${pending.title}” will be removed from this browser. This can’t be undone.`} confirmLabel="Delete chat" onConfirm={()=>{onDelete(pending.id);setPending(null)}} onCancel={()=>setPending(null)}/>}</div>}

function ConversationPanel({items,selected,onSelect,onNew,onDelete,open,onClose}:{items:Conversation[];selected:string;onSelect:(x:string)=>void;onNew:()=>void;onDelete:(id:string)=>void;open:boolean;onClose:()=>void}){const panel=useRef<HTMLElement>(null);const close=useRef(onClose);close.current=onClose;
  // Drawer below 1280px: move focus in on open, restore it on close, close on Escape. (Wide screens never set open.)
  useEffect(()=>{if(!open)return;const opener=document.activeElement instanceof HTMLElement?document.activeElement:null;panel.current?.querySelector<HTMLElement>(".search input")?.focus();const onKey=(e:KeyboardEvent)=>{if(e.key==="Escape")close.current()};document.addEventListener("keydown",onKey);return()=>{document.removeEventListener("keydown",onKey);opener?.focus()}},[open]);return <aside ref={panel} id="chat-history" className={`conversation-panel ${open?"open":""}`} aria-label="Chat history"><div className="conversation-top"><div className="conversation-title"><strong>Chat history</strong><div><Button variant="icon" icon="plus" onClick={onNew} aria-label="New chat"/><Button variant="icon" icon="close" className="history-close" onClick={onClose} aria-label="Close chat history"/></div></div></div><HistoryList items={items} selected={selected} onSelect={onSelect} onDelete={onDelete}/></aside>}

function ScheduleCard({proposal,onAdd,onDismiss}:{proposal:ScheduleProposal;onAdd:()=>void;onDismiss:()=>void}){return <div className="schedule-card"><strong>{proposal.title}</strong><span>{fmt(proposal.date)}{proposal.time?` · ${proposal.time}`:""}</span>{proposal.reminder&&<small>Reminder: {fmt(proposal.reminder)}</small>}<div className="schedule-actions"><Button onClick={onAdd}>Add to {proposal.type.toLowerCase().includes("assignment")||proposal.type.toLowerCase()==="project"?"Schoolwork & Calendar":"Calendar"}</Button><Button variant="ghost" onClick={onDismiss}>Don’t add</Button></div></div>}
// Time label for a message: "10:40 AM" today, "Oct 9, 10:40 AM" otherwise. Older messages have no createdAt.
const messageTime=(iso:string)=>{const d=new Date(iso);if(Number.isNaN(d.getTime()))return "";return d.toDateString()===new Date().toDateString()?d.toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit"}):d.toLocaleString("en-US",{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"})};
const SUGGESTIONS:{icon:IconName;title:string;prompt:string}[]=[
  {icon:"shield",title:"Replace a school ID",prompt:"How can I get a replacement school ID?"},
  {icon:"calendar",title:"Track an exam",prompt:"I have a Database Systems exam on October 30."},
  {icon:"document",title:"Plan an assignment",prompt:"My Web Development assignment is due October 15."},
];
function AiAvatar(){return <span className="ai-avatar" aria-hidden="true"><Eagle size="sm"/></span>}

function Chat({conversation,onSend,onAction,sending,historyOpen,onOpenHistory,onNew,failure,onRetry,onFailureProposal}:{conversation:Conversation|null;onSend:(text:string)=>void;onAction:(id:string,action:"add"|"dismiss")=>void;sending:boolean;historyOpen:boolean;onOpenHistory:()=>void;onNew:()=>void;failure?:Failure;onRetry:()=>void;onFailureProposal:(action:"add"|"dismiss")=>void}){
  const [value,setValue]=useState("");
  const bottom=useRef<HTMLDivElement>(null);
  const input=useRef<HTMLTextAreaElement>(null);
  useEffect(()=>{bottom.current?.scrollIntoView({behavior:"smooth"});},[conversation?.messages.length,sending,!!failure]);
  // Grow the composer with its content (up to the CSS max-height).
  useLayoutEffect(()=>{const el=input.current;if(!el)return;el.style.height="auto";el.style.height=`${Math.min(el.scrollHeight,180)}px`},[value]);
  // Return focus to the composer once a reply (or failure) arrives.
  const wasSending=useRef(false);useEffect(()=>{if(wasSending.current&&!sending)input.current?.focus();wasSending.current=sending},[sending]);
  const send=(e:FormEvent)=>{e.preventDefault();if(value.trim()&&!sending){onSend(value.trim());setValue("")}};
  const onKey=(e:React.KeyboardEvent<HTMLTextAreaElement>)=>{if(e.key==="Enter"&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();e.currentTarget.form?.requestSubmit()}};
  const pickSuggestion=(prompt:string)=>{setValue(prompt);input.current?.focus()};
  const hasMessages=!!conversation&&conversation.messages.length>0;
  return <main className="chat-view">
    <header className="chat-header">
      <Button variant="icon" icon="menu" className="chat-history-toggle" onClick={onOpenHistory} aria-label="Open chat history" aria-expanded={historyOpen} aria-controls="chat-history"/>
      <div className="chat-title"><Eagle size="sm"/><div className="chat-identity"><h1 className="chat-title-text">{hasMessages?conversation!.title:"New chat"}</h1><span>EagleDesk school helpdesk</span></div></div>
      <div className="chat-header-actions"><Button variant="icon" icon="plus" className="chat-new" onClick={onNew} aria-label="New chat"/></div>
    </header>
    <div className="messages">
      {hasMessages ? conversation!.messages.map(m=>{const time=m.createdAt?messageTime(m.createdAt):"";return (
        <div key={m.id} className={`message ${m.from}`}>
          {m.from==="ai"&&<AiAvatar/>}
          <div>
            {m.from==="ai"?<div className="message-meta"><span className="message-name">EagleDesk</span>{time&&<time className="message-time" dateTime={m.createdAt}>{time}</time>}</div>:<span className="message-name">You</span>}
            {m.schedule?<div className="bubble schedule-results">{m.schedule.request==="full"&&<p>{m.text}</p>}{m.schedule.entries.map(entry=><div className="schedule-entry" key={`${entry.section}-${entry.courseCode}`}><strong>{entry.day}</strong><div><span className="course-code">{entry.courseCode}</span>{entry.courseName}</div><div className="tabular">{entry.startTime} - {entry.endTime}</div><div>{entry.room?`Room ${entry.room}`:"Room not listed"}</div></div>)}</div>
              :m.from==="ai"?<div className="bubble formatted"><FormattedText text={m.text}/></div>:<div className="bubble">{m.text}</div>}
            {m.from==="user"&&time&&<time className="message-time" dateTime={m.createdAt}>{time}</time>}
            {m.from==="ai"&&m.sources&&m.sources.length>0&&<div className="sources"><span>Sources</span><ul>{m.sources.map(s=><li key={s.id}>{s.title}</li>)}</ul></div>}
            {m.proposal&&!m.dismissed&&<ScheduleCard proposal={m.proposal} onAdd={()=>onAction(m.id,"add")} onDismiss={()=>onAction(m.id,"dismiss")}/>}
          </div>
        </div>
      )}) : <div className="welcome"><div className="orb"><Eagle size="lg"/></div><h1>How can I help?</h1><p>Ask a school question, or tell me about a deadline to organize your schedule.</p><div className="suggestions">{SUGGESTIONS.map(s=><button key={s.prompt} onClick={()=>pickSuggestion(s.prompt)}><span className="suggestion-head"><span className="icon-wrap"><Icon name={s.icon} size={17}/></span><strong>{s.title}</strong></span><span className="suggestion-prompt">“{s.prompt}”</span></button>)}</div></div>}
      {failure&&!sending&&<div className="message ai"><AiAvatar/><div><div className="message-error" role="alert"><div><strong>EagleDesk couldn’t answer</strong><p>{failure.error}</p></div><Button variant="secondary" onClick={onRetry}>Retry</Button></div>{failure.proposal&&!failure.added&&<ScheduleCard proposal={failure.proposal} onAdd={()=>onFailureProposal("add")} onDismiss={()=>onFailureProposal("dismiss")}/>}</div></div>}
      {sending&&<div className="message ai" role="status" aria-live="polite"><AiAvatar/><div><div className="message-meta"><span className="message-name">EagleDesk</span></div><div className="bubble"><span className="typing" aria-hidden="true"><i/><i/><i/></span><span className="sr-only">EagleDesk is thinking</span></div></div></div>}
      <div ref={bottom}/>
    </div>
    <form className="composer" onSubmit={send}>
      <textarea ref={input} rows={1} value={value} onChange={e=>setValue(e.target.value)} onKeyDown={onKey} placeholder="Ask EagleDesk or tell it about a due date…" aria-label="Message EagleDesk" aria-describedby="composer-hint" enterKeyHint="send" disabled={sending}/>
      <div className="composer-footer"><span id="composer-hint" className="composer-hint">Enter to send, Shift+Enter for a new line</span><Button className="send-button" icon="send" aria-label="Send" disabled={sending||!value.trim()}/></div>
    </form>
  </main>
}

const EVENT_TYPES=["Exam","Quiz","Assignment","Project","Presentation","Meeting","Deadline","Other"];
// Reads an existing event time ("9am", "9:30 pm", "14:05") as "HH:MM" for a time input; "" if it cannot be read.
const toTimeInput=(t?:string)=>{if(!t)return "";const m=t.trim().match(/^(\d{1,2})(?::(\d{2}))?\s*(am|pm)?$/i);if(!m)return "";let h=Number(m[1]);const min=m[2]??"00";const ap=m[3]?.toLowerCase();if(Number(min)>59)return "";if(ap){if(h<1||h>12)return "";if(ap==="pm"&&h<12)h+=12;if(ap==="am"&&h===12)h=0}else if(h>23)return "";return `${String(h).padStart(2,"0")}:${min}`};

// Add or edit a personal calendar event using the existing event shape. Fields the student leaves
// untouched keep their original saved value (for example a "9am" time written by the chat parser).
function EventDialog({initial,onSave,onClose}:{initial:ScheduleProposal|null;onSave:(e:ScheduleProposal)=>void;onClose:()=>void}){const titleId=useId();const [error,setError]=useState("");const timeDefault=toTimeInput(initial?.time);const types=initial?.type&&!EVENT_TYPES.includes(initial.type)?[initial.type,...EVENT_TYPES]:EVENT_TYPES;
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const titleIn=String(f.get("title")||""),date=String(f.get("date")||""),timeIn=String(f.get("time")||""),reminder=String(f.get("reminder")||""),descIn=String(f.get("description")||"");
    if(!titleIn.trim()||!date){setError("Add a title and a date.");return}
    if(reminder&&reminder>date){setError("The reminder date must be on or before the event date.");return}
    const keep=<T,>(input:string,original:T|undefined,fallback:T|undefined)=>initial&&input===(original??"")?original:fallback;
    onSave({...(initial??{}),title:keep(titleIn,initial?.title,titleIn.trim())||titleIn.trim(),type:String(f.get("type")),date,time:initial&&timeIn===timeDefault?initial.time:(timeIn||undefined),reminder:reminder||undefined,description:keep(descIn,initial?.description,descIn.trim()||undefined)})};
  return <Dialog labelledBy={titleId} onClose={onClose}><form className="form-modal" onSubmit={submit} noValidate><div className="modal-title"><h2 id={titleId}>{initial?"Edit event":"Add event"}</h2><button type="button" onClick={onClose} aria-label="Close"><Icon name="close"/></button></div><label>Title<input name="title" required defaultValue={initial?.title}/></label><div className="form-grid"><label>Type<select name="type" defaultValue={initial?.type||"Exam"}>{types.map(t=><option key={t}>{t}</option>)}</select></label><label>Date<input name="date" type="date" required defaultValue={initial?.date??localDate(new Date())}/></label></div><div className="form-grid"><label><span className="label-row">Time <span className="field-hint">Optional</span></span><input name="time" type="time" defaultValue={timeDefault}/>{initial?.time&&!timeDefault&&<span className="field-hint">Saved as “{initial.time}”. Leave empty to keep it.</span>}</label><label><span className="label-row">Reminder date <span className="field-hint">Optional</span></span><input name="reminder" type="date" defaultValue={initial?.reminder}/></label></div><label><span className="label-row">Description <span className="field-hint">Optional</span></span><textarea name="description" defaultValue={initial?.description}/></label>{error&&<p className="field-error" role="alert">{error}</p>}<div className="modal-actions"><Button variant="secondary" type="button" onClick={onClose}>Cancel</Button><Button type="submit">{initial?"Save changes":"Add event"}</Button></div></form></Dialog>}

function CalendarPage({events,onDelete,onSave}:{events:ScheduleProposal[];onDelete:(i:number)=>void;onSave:(e:ScheduleProposal,index:number|null)=>void}){const [month,setMonth]=useState(()=>{const now=new Date();return new Date(now.getFullYear(),now.getMonth(),1)});const [editing,setEditing]=useState<{index:number|null}|null>(null);const [pendingDelete,setPendingDelete]=useState<number|null>(null);const year=month.getFullYear(),mo=month.getMonth(),first=new Date(year,mo,1).getDay(),count=new Date(year,mo+1,0).getDate(),today=localDate(new Date());const monthEvents=events.filter(e=>new Date(`${e.date}T12:00`).getMonth()===mo&&new Date(`${e.date}T12:00`).getFullYear()===year);return <Page title="Personal Calendar" subtitle="Your exams, deadlines, and personal school events." actions={<Button icon="plus" onClick={()=>setEditing({index:null})}>Add event</Button>}><div className="calendar-layout"><section className="card calendar-card" aria-label="Month view"><div className="calendar-head"><Button variant="icon" icon="chevron" className="prev" onClick={()=>setMonth(new Date(year,mo-1,1))} aria-label="Previous month"/><strong aria-live="polite">{month.toLocaleDateString("en-US",{month:"long",year:"numeric"})}</strong><Button variant="icon" icon="chevron" onClick={()=>setMonth(new Date(year,mo+1,1))} aria-label="Next month"/></div><div className="week" aria-hidden="true">{"Sun Mon Tue Wed Thu Fri Sat".split(" ").map(d=><span key={d}>{d}</span>)}</div><div className="days">{Array.from({length:first},(_,i)=><div key={`e${i}`} aria-hidden="true"/>)}{Array.from({length:count},(_,i)=>{const d=i+1,date=`${year}-${String(mo+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`,has=events.some(e=>e.date===date),isToday=date===today;return <div key={d} className={`${isToday?"today":""} ${has?"has-event":""}`}>{d}{has&&<i/>}{(isToday||has)&&<span className="sr-only">{[isToday&&"today",has&&"has events"].filter(Boolean).join(", ")}</span>}</div>})}</div></section><section className="card"><h3>Personal events this month</h3><div className="event-list">{monthEvents.length?monthEvents.sort((a,b)=>a.date.localeCompare(b.date)).map((e,i)=><div className="event" key={`${e.date}${e.title}${i}`}><strong>{new Date(`${e.date}T12:00:00`).toLocaleDateString("en-US",{month:"short",day:"numeric"})}</strong><div><b>{e.title}</b><span>{e.type}{e.time?` · ${e.time}`:""}</span></div><div className="event-actions"><button aria-label={`Edit ${e.title}`} onClick={()=>setEditing({index:events.indexOf(e)})}><Icon name="edit" size={16}/></button><button className="danger-hover" aria-label={`Delete ${e.title}`} onClick={()=>setPendingDelete(events.indexOf(e))}><Icon name="trash" size={16}/></button></div></div>):<p className="empty-hint">No personal events this month. Add one here, or from Chat or Schoolwork.</p>}</div></section><section className="card official-calendar"><h3>Official school calendar</h3><p>EagleDesk does not include the current official calendar yet. Check the latest academic calendar published by New Era University.</p><a className="external-link" href="https://neu.edu.ph/main/img/School_calendar.pdf" target="_blank" rel="noopener noreferrer">Open the official NEU calendar<span className="sr-only"> (opens in a new tab)</span></a></section></div>{editing&&<EventDialog initial={editing.index===null?null:events[editing.index]??null} onClose={()=>setEditing(null)} onSave={ev=>{onSave(ev,editing.index);setEditing(null);const d=new Date(`${ev.date}T12:00:00`);if(!Number.isNaN(d.getTime()))setMonth(new Date(d.getFullYear(),d.getMonth(),1))}}/>}{pendingDelete!==null&&events[pendingDelete]&&<ConfirmDialog title="Delete this event?" message={`“${events[pendingDelete].title}” will be removed from your personal calendar.`} confirmLabel="Delete event" onConfirm={()=>{onDelete(pendingDelete);setPendingDelete(null)}} onCancel={()=>setPendingDelete(null)}/>}</Page>}

function SchoolworkPage({items,onSave,onDelete,onToggle}:{items:Schoolwork[];onSave:(item:Schoolwork)=>void;onDelete:(id:string)=>void;onToggle:(id:string)=>void}){const [editing,setEditing]=useState<Schoolwork|null>(null);const [showForm,setShowForm]=useState(false);const [pendingDelete,setPendingDelete]=useState<Schoolwork|null>(null);const pending=items.filter(x=>x.status==="pending").sort((a,b)=>a.dueDate.localeCompare(b.dueDate)),done=items.filter(x=>x.status==="completed"),today=localDate(new Date());const begin=(item?:Schoolwork)=>{setEditing(item||{id:uid(),title:"",type:"Assignment",date:"",dueDate:"",subject:"",status:"pending",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});setShowForm(true)};const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const date=String(f.get("dueDate"));onSave({...editing!,title:String(f.get("title")),subject:String(f.get("subject")),type:String(f.get("type")),dueDate:date,date,dueTime:String(f.get("dueTime")||"")||undefined,reminder:f.get("reminder")==="yes"?daysLater(date,-1):undefined,description:String(f.get("description")||"")||undefined,updatedAt:new Date().toISOString()});setShowForm(false)};const list=(arr:Schoolwork[])=><div className="work-list">{arr.map(w=><article className="work-item" key={w.id}><div className="work-date">{fmt(w.dueDate)}{w.dueTime&&<span>{w.dueTime}</span>}</div><div className="work-main"><strong>{w.title}{w.status==="pending"&&w.dueDate<today&&<span className="badge badge-danger">Overdue</span>}</strong><span>{[w.subject,w.type].filter(Boolean).join(" · ")}</span>{w.reminder&&<small>Reminder set for {fmt(w.reminder)}</small>}</div><div className="work-actions"><Button variant="secondary" onClick={()=>onToggle(w.id)}>{w.status==="completed"?"Reopen":"Complete"}</Button><Button variant="icon" icon="edit" onClick={()=>begin(w)} aria-label="Edit schoolwork"/><Button variant="icon" icon="trash" onClick={()=>setPendingDelete(w)} aria-label={`Delete ${w.title}`}/></div></article>)}</div>;return <Page title="Schoolwork" subtitle="Keep assignments, projects, and deadlines in one place." actions={<Button icon="plus" onClick={()=>begin()}>Add schoolwork</Button>}><section className="card work-section"><h3>Upcoming <span>{pending.length}</span></h3>{pending.length?list(pending):<p className="empty-hint">No upcoming schoolwork. Add a task or tell EagleDesk in Chat.</p>}</section>{done.length>0&&<details className="card work-section completed-section"><summary>Completed <span>{done.length}</span></summary>{list(done)}</details>}{showForm&&<Dialog labelledBy="schoolwork-dialog-title" onClose={()=>setShowForm(false)}><form className="form-modal" onSubmit={submit}><div className="modal-title"><h2 id="schoolwork-dialog-title">{items.some(x=>x.id===editing?.id)?"Edit schoolwork":"Add schoolwork"}</h2><button type="button" onClick={()=>setShowForm(false)} aria-label="Close"><Icon name="close"/></button></div><label>Title<input name="title" required defaultValue={editing?.title}/></label><div className="form-grid"><label>Subject<input name="subject" defaultValue={editing?.subject}/></label><label>Type<select name="type" defaultValue={editing?.type||"Assignment"}>{["Assignment","Project","Exam","Quiz","Presentation","Other"].map(x=><option key={x}>{x}</option>)}</select></label></div><div className="form-grid"><label>Due date<input name="dueDate" type="date" required defaultValue={editing?.dueDate}/></label><label>Due time<input name="dueTime" type="time" defaultValue={editing?.dueTime}/></label></div><label>Description<textarea name="description" defaultValue={editing?.description}/></label><label className="check-label"><input type="checkbox" name="reminder" value="yes" defaultChecked={!!editing?.reminder}/> Remind me one day before</label><div className="modal-actions"><Button variant="secondary" type="button" onClick={()=>setShowForm(false)}>Cancel</Button><Button type="submit">Save schoolwork</Button></div></form></Dialog>}{pendingDelete&&<ConfirmDialog title="Delete this schoolwork?" message={`“${pendingDelete.title}” and its calendar entry will be removed. This can’t be undone.`} confirmLabel="Delete schoolwork" onConfirm={()=>{onDelete(pendingDelete.id);setPendingDelete(null)}} onCancel={()=>setPendingDelete(null)}/>}</Page>}

function NotificationsPage({items,onRead,onClear}:{items:Notice[];onRead:(id:string)=>void;onClear:()=>void}){const [confirmClear,setConfirmClear]=useState(false);return <Page title="Notifications" subtitle="Your personal reminders and school updates." actions={items.length>0?<Button variant="secondary" onClick={()=>setConfirmClear(true)}>Clear all</Button>:null}><div className="notification-list">{items.length===0?<div className="empty-state"><strong>You’re all caught up</strong><p>Reminders for your schoolwork and personal events will appear here.</p></div>:items.map(n=><button key={n.id} className={`card notification ${n.read?"":"unread"}`} onClick={()=>onRead(n.id)}><div className="notification-icon"><Icon name={n.type==="Reminder"?"calendar":"info"}/></div><div><strong>{n.title}</strong><p>{n.message}</p><time dateTime={n.createdAt}>{new Date(n.createdAt).toLocaleString("en-US",{month:"short",day:"numeric",year:"numeric",hour:"numeric",minute:"2-digit"})}</time></div>{!n.read&&<i className="unread-dot"/>}</button>)}</div>{confirmClear&&<ConfirmDialog title="Clear all notifications?" message="All reminders in this list will be removed. Your schoolwork and calendar events are not affected." confirmLabel="Clear all" onConfirm={()=>{onClear();setConfirmClear(false)}} onCancel={()=>setConfirmClear(false)}/>}</Page>}
function SettingsPage({theme,setTheme,onSignOut}:{theme:string;setTheme:(v:"dark"|"light")=>void;onSignOut:()=>void}){const supported="Notification" in window;const [permission,setPermission]=useState<NotificationPermission>(()=>supported?Notification.permission:"default");const enable=()=>{if(supported)Notification.requestPermission().then(setPermission).catch(()=>{})};const notify=!supported?<span>Not supported in this browser</span>:permission==="granted"?<span className="setting-status">Enabled</span>:permission==="denied"?<span>Blocked in browser settings</span>:<Button variant="secondary" onClick={enable}>Enable</Button>;return <Page title="Settings" subtitle="Manage your EagleDesk preferences."><div className="settings-card card"><Setting icon="sun" title="Appearance" desc="Choose how EagleDesk looks."><fieldset className="segmented"><legend className="sr-only">Theme</legend>{(["light","dark"] as const).map(t=><label key={t}><input type="radio" name="theme" value={t} checked={theme===t} onChange={()=>setTheme(t)}/><Icon name={t==="light"?"sun":"moon"} size={16}/>{t==="light"?"Light":"Dark"}</label>)}</fieldset></Setting><Setting icon="bell" title="Browser notifications" desc="Show reminders as browser notifications while EagleDesk is open.">{notify}</Setting><Setting icon="shield" title="Privacy" desc="Your chats, calendar, and schoolwork are saved in this browser for your account.">{null}</Setting><Setting icon="logout" title="Sign out" desc="Sign out of EagleDesk on this browser."><Button variant="danger" onClick={onSignOut}>Sign out</Button></Setting></div></Page>}
function Setting({icon,title,desc,children}:{icon:IconName;title:string;desc:string;children:ReactNode}){return <div className="setting-row"><div className="setting-icon"><Icon name={icon}/></div><div className="setting-copy"><strong>{title}</strong><p>{desc}</p></div><div className="setting-control">{children}</div></div>}
function ProfilePage({onSettings,onSignOut}:{onSettings:()=>void;onSignOut:()=>void}){const user=useContext(UserContext);return <Page title="Student Profile" subtitle="Your EagleDesk student information."><div className="card profile-details"><Avatar/><div className="profile-fields">{[["Name",user.name],["Student ID",user.studentId],["Program / Course",user.program],["Section",user.section],["Email",user.email]].map(([k,v])=><div key={k}><span>{k}</span><strong className={v==="Not set"?"muted":""}>{v}</strong></div>)}</div></div><div className="profile-actions"><Button variant="secondary" onClick={onSettings}>Settings</Button><Button variant="danger" icon="logout" onClick={onSignOut}>Sign out</Button></div></Page>}
