function ContactPage(){return <Page title="Contact Staff" subtitle="Find the right office for your concern."><div className="staff-grid">{OFFICES.map(o=><section className="staff-card" key={o.name}><h3>{o.name}</h3><p>{o.about}</p><div className="staff-contact">{o.location&&<span><Icon name="map" size={16}/>{o.location}</span>}{o.email&&<a href={`mailto:${o.email}`}><Icon name="mail" size={16}/>{o.email}</a>}{o.phone&&(o.tel?<a href={`tel:${o.tel}`}><Icon name="phone" size={16}/>{o.phone}</a>:<span><Icon name="phone" size={16}/>{o.phone}</span>)}</div>{o.hours&&<p className="staff-hours">{o.hours}</p>}</section>)}</div><p className="contact-source">Details are from the official New Era University website. Offices and contact details can change, so check <a href="https://neu.edu.ph/main/contact-us" target="_blank" rel="noopener noreferrer">neu.edu.ph<span className="sr-only"> (opens in a new tab)</span></a> for the latest information.</p></Page>}
function AvatarMenu({anchor,onPage,onSignOut,onClose}:{anchor:"top"|"side";onPage:(p:string)=>void;onSignOut:()=>void;onClose:()=>void}){const ref=useRef<HTMLDivElement>(null);useDismiss(ref,onClose,".global-avatar,.profile-button");useEffect(()=>{ref.current?.querySelector("button")?.focus()},[]);return <div ref={ref} id="profile-menu" className={`avatar-menu ${anchor==="side"?"from-sidebar":""}`} role="group" aria-label="Profile menu"><button onClick={()=>onPage("profile")}>Student Profile</button><button onClick={()=>onPage("settings")}>Settings</button><button onClick={onSignOut}>Sign out</button></div>}

function ReminderTicker({data,onDue}:{data:Data;onDue:(notice:Notice)=>void}){const sent=useRef(new Set<string>());useEffect(()=>{const check=()=>{const now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}-${String(now.getDate()).padStart(2,"0")}`;const items=[...data.events.map(e=>({...e,reminderId:`reminder:${e.title}:${e.date}`})),...data.schoolwork.filter(w=>w.status==="pending").map(w=>({...w,reminderId:`reminder:${w.title}:${w.dueDate}`}))];for(const item of items){if(!item.reminder||item.reminder>today||(item.reminder===today&&now.getHours()<9))continue;const key=item.reminderId;if(sent.current.has(key)||data.notifications.some(n=>n.relatedId===key))continue;sent.current.add(key);const dateText=item.date===daysLater(today,1)?"is due tomorrow":`is due ${fmt(item.date)}`;const notice:Notice={id:uid(),title:`Reminder: ${item.title}`,message:`${item.title} ${dateText}.`,type:"Reminder",createdAt:now.toISOString(),read:false,relatedId:key};onDue(notice);if("Notification"in window&&Notification.permission==="granted")new Notification(notice.title,{body:notice.message})}};check();const timer=window.setInterval(check,60_000);return()=>window.clearInterval(timer)},[data,onDue]);return null}

function Workspace({onSignOut}:{onSignOut:()=>Promise<string|null>}){const user=useContext(UserContext);const [data,setData]=useState<Data>(()=>load(user.key));const [page,setPage]=useState("chats");const [selected,setSelected]=useState("");const [menu,setMenu]=useState<false|"top"|"side">(false);const [toast,setToast]=useState("");const [sending,setSending]=useState(false);const [historyOpen,setHistoryOpen]=useState(false);const [failures,setFailures]=useState<Record<string,Failure>>({});useEffect(()=>{localStorage.setItem(storeKey(user.key),JSON.stringify(data))},[data]);const unread=data.notifications.filter(n=>!n.read).length;const active=data.conversations.find(c=>c.id===selected)||null;const makeWork=(p:ScheduleProposal):Schoolwork=>({id:uid(),...p,subject:p.title.replace(/\s+(Exam|Assignment|Project|Quiz|Presentation)$/i,""),dueDate:p.date,status:"pending",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});const addProposal=(conversationId:string,messageId:string,p:ScheduleProposal)=>{const workCandidate=/assignment|project|homework/i.test(p.type);setData(d=>{const work=workCandidate?makeWork(p):null;return {...d,events:[...d.events,p],schoolwork:work?[...d.schoolwork,work]:d.schoolwork,conversations:d.conversations.map(c=>c.id===conversationId?{...c,messages:c.messages.map(m=>m.id===messageId?{...m,dismissed:true}:m)}:c)}});setToast(workCandidate?"Added to Schoolwork and Personal Calendar":"Added to Personal Calendar");setTimeout(()=>setToast(""),2600)};const AUTO_ADD=/\b(remind me|schedule|add (this|it)|put (this|it))\b/i;
  // Asks /api/ask for an answer to `text` in conversation `id`. On success an AI message is saved (with sources
  // and createdAt when available). On failure nothing is saved as a reply: the error is kept in memory with Retry.
  // `added` says whether this message's schedule proposal was already added (so Retry cannot add it twice).
  const requestAnswer=async(id:string,text:string,p:ScheduleProposal|null,added:boolean)=>{setSending(true);let answer="";let scheduleResponse:StructuredSchedule|undefined;let sources:Source[]=[];try{if(!supabase)throw new Error("Your sign-in session is unavailable. Please sign in again.");const {data:sessionData,error:sessionError}=await supabase.auth.getSession();if(sessionError||!sessionData.session?.access_token)throw new Error("Your sign-in session has expired. Please sign in again.");const response=await fetch("/api/ask",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${sessionData.session.access_token}`},body:JSON.stringify({message:text})});const payload=await response.json().catch(()=>null) as {answer?:unknown;error?:{message?:unknown};schedule?:StructuredSchedule;sources?:unknown}|null;if(!response.ok)throw new Error(typeof payload?.error?.message==="string"?payload.error.message:"The AI service is temporarily unavailable. Please try again.");if(typeof payload?.answer!=="string"||!payload.answer.trim())throw new Error("The AI service returned an empty response. Please try again.");answer=payload.answer.trim();scheduleResponse=payload.schedule;
      // Keep only well-formed source references exactly as the API returned them; never invent any.
      if(Array.isArray(payload.sources))sources=payload.sources.flatMap((s:unknown)=>{const o=s as {id?:unknown;title?:unknown;category?:unknown}|null;return o&&typeof o.id==="string"&&typeof o.title==="string"&&o.title.trim()?[{id:o.id,title:o.title.trim(),...(typeof o.category==="string"?{category:o.category}:{})}]:[]})}
    catch(error:unknown){const message=error instanceof TypeError?"Couldn’t reach EagleDesk. Check your internet connection and try again.":error instanceof Error?error.message:"The AI service is temporarily unavailable. Please try again.";let nowAdded=added;if(p&&!added&&AUTO_ADD.test(text)){addProposal(id,"",p);nowAdded=true}setFailures(f=>({...f,[id]:{text,error:message,proposal:p||undefined,added:nowAdded}}));setSending(false);return}
    setSending(false);const ai:Message={id:uid(),from:"ai",text:answer,proposal:p||undefined,schedule:scheduleResponse,createdAt:new Date().toISOString(),...(sources.length?{sources}:{}),...(p&&added?{dismissed:true}:{})};setData(d=>{const c=d.conversations.find(x=>x.id===id);if(!c)return d;const next={...c,updatedAt:new Date().toISOString(),messages:[...c.messages,ai]};return {...d,conversations:[next,...d.conversations.filter(x=>x.id!==id)]}});if(p&&!added&&AUTO_ADD.test(text))addProposal(id,ai.id,p)};
  const clearFailure=(id:string)=>setFailures(f=>{if(!(id in f))return f;const next={...f};delete next[id];return next});
  const sendMessage=async(text:string)=>{const p=/\b(i have|my|remind me|add (this|it)|put (this|it)|schedule my)\b/i.test(text)?parseSchedule(text):null;const id=selected||uid(),now=new Date().toISOString();const userMsg:Message={id:uid(),from:"user",text,createdAt:now};setData(d=>{let c=d.conversations.find(x=>x.id===id);if(!c)c={id,title:text.slice(0,42),createdAt:now,updatedAt:now,messages:[]};const next={...c,title:c.messages.length?c.title:text.slice(0,42),updatedAt:now,messages:[...c.messages,userMsg]};return {...d,conversations:[next,...d.conversations.filter(x=>x.id!==id)]}});setSelected(id);clearFailure(id);await requestAnswer(id,text,p,false)};
  // Retry re-asks the same question without adding another copy of the student's message.
  const retry=(id:string)=>{const f=failures[id];if(!f||sending)return;clearFailure(id);void requestAnswer(id,f.text,f.proposal??null,f.added)};
  const failureProposal=(id:string,what:"add"|"dismiss")=>{const f=failures[id];if(!f?.proposal||f.added)return;if(what==="add")addProposal(id,"",f.proposal);setFailures(all=>({...all,[id]:{...f,added:true}}))};const action=(messageId:string,what:"add"|"dismiss")=>{const m=active?.messages.find(x=>x.id===messageId);if(!active||!m?.proposal)return;if(what==="add")addProposal(active.id,messageId,m.proposal);else setData(d=>({...d,conversations:d.conversations.map(c=>c.id===active.id?{...c,messages:c.messages.map(x=>x.id===messageId?{...x,dismissed:true}:x)}:c)}))};const updateWork=(w:Schoolwork)=>setData(d=>({...d,schoolwork:d.schoolwork.some(x=>x.id===w.id)?d.schoolwork.map(x=>x.id===w.id?w:x):[w,...d.schoolwork],events:d.events.some(x=>x.title===w.title&&x.date===w.date)?d.events:[...d.events,{title:w.title,type:w.type,date:w.dueDate,time:w.dueTime,reminder:w.reminder,description:w.description}]}));const deleteWork=(id:string)=>setData(d=>{const w=d.schoolwork.find(x=>x.id===id);return {...d,schoolwork:d.schoolwork.filter(x=>x.id!==id),events:d.events.filter(e=>!(w&&e.title===w.title&&e.date===w.dueDate))}});const toggleWork=(id:string)=>setData(d=>({...d,schoolwork:d.schoolwork.map(w=>w.id===id?{...w,status:w.status==="pending"?"completed":"pending",updatedAt:new Date().toISOString()}:w)}));const createNew=()=>{setSelected("");setPage("chats");setHistoryOpen(false)};const selectChat=(id:string)=>{setSelected(id);setPage("chats");setHistoryOpen(false)};const deleteChat=(id:string)=>{setData(d=>({...d,conversations:d.conversations.filter(c=>c.id!==id)}));if(selected===id)setSelected("")};const signOut=async()=>{setMenu(false);const error=await onSignOut();if(error){setToast(error);setTimeout(()=>setToast(""),4000)}};const profileClose=()=>setMenu(false);const flash=(message:string)=>{setToast(message);setTimeout(()=>setToast(""),2600)};const setTheme=(theme:"dark"|"light")=>{try{localStorage.setItem(THEME_KEY,theme)}catch{}setData(d=>({...d,theme}))};let content:ReactNode=page==="calendar"?<CalendarPage events={data.events} onDelete={i=>setData(d=>({...d,events:d.events.filter((_,n)=>n!==i)}))} onSave={(ev,i)=>{setData(d=>({...d,events:i===null?[...d.events,ev]:d.events.map((x,n)=>n===i?ev:x)}));flash(i===null?"Event added to Personal Calendar":"Event updated")}}/>:page==="schoolwork"?<SchoolworkPage items={data.schoolwork} onSave={w=>{updateWork(w);flash("Schoolwork saved")}} onDelete={deleteWork} onToggle={toggleWork}/>:page==="notifications"?<NotificationsPage items={data.notifications} onRead={id=>setData(d=>({...d,notifications:d.notifications.map(n=>n.id===id?{...n,read:true}:n)}))} onClear={()=>setData(d=>({...d,notifications:[]}))}/>:page==="settings"?<SettingsPage theme={data.theme} setTheme={setTheme} onSignOut={signOut}/>:page==="profile"?<ProfilePage onSettings={()=>setPage("settings")} onSignOut={signOut}/>:page==="contact"?<ContactPage/>:null;return <div className={`app-shell theme-${data.theme}`}><ReminderTicker data={data} onDue={notice=>setData(d=>d.notifications.some(n=>n.relatedId===notice.relatedId)?d:{...d,notifications:[notice,...d.notifications]})}/><Sidebar page={page} setPage={setPage} openProfile={()=>setMenu(v=>v?false:"side")} unread={unread} menuOpen={!!menu} history={{items:data.conversations,selected,onSelect:selectChat,onNew:createNew,onDelete:deleteChat}}/>{menu&&<AvatarMenu anchor={menu} onPage={p=>{setPage(p);setMenu(false)}} onSignOut={signOut} onClose={profileClose}/>}<button className="global-avatar" onClick={()=>setMenu(v=>v?false:"top")} aria-label="Open profile menu" aria-expanded={!!menu} aria-controls="profile-menu"><Avatar/></button><div className="workspace">{page==="chats"?<><ConversationPanel items={data.conversations} selected={selected} onSelect={selectChat} onNew={createNew} onDelete={deleteChat} open={historyOpen} onClose={()=>setHistoryOpen(false)}/>{historyOpen&&<div className="history-scrim" onClick={()=>setHistoryOpen(false)} aria-hidden="true"/>}<Chat conversation={active} onSend={sendMessage} onAction={action} sending={sending} historyOpen={historyOpen} onOpenHistory={()=>setHistoryOpen(true)} onNew={createNew} failure={active?failures[active.id]:undefined} onRetry={()=>active&&retry(active.id)} onFailureProposal={what=>active&&failureProposal(active.id,what)}/></>:content}</div><MobileNav page={page} setPage={setPage} unread={unread}/><div role="status" aria-live="polite">{toast&&<div className="toast">{toast}</div>}</div></div>}

export default function App(){
  const auth=useAuth();
  if(auth.loading)return <AuthLoading/>;
  if(auth.session&&auth.recovery)return <SetNewPassword onSubmit={auth.setNewPassword} onCancel={auth.signOut}/>;
  if(!auth.session)return <Login configured={auth.configured} initialError={auth.sessionError} onSignIn={auth.signIn} onForgotPassword={auth.sendResetEmail}/>;
  const student=toStudentUser(auth.session.user);
  return <UserContext.Provider value={student}><Workspace key={student.key} onSignOut={auth.signOut}/></UserContext.Provider>;
}
